<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetCodeVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetTenantVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetContentHtmlVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetEnabledVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetVersionVO;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Create\TemplateSnippetCreateParams;
use PHPUnit\Framework\TestCase;

final class TemplateSnippetCreateParamsUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new TemplateSnippetCreateParams();
        $codeOneValue = 'one';
        $codeOtherValue = 'other';
        $copy = $value->code($codeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCode());
        $this->assertNotEquals('other', $value->getCode());
        $this->assertEquals('one', $value->getCodeOrCurrent(TemplateSnippetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('other', $value->getCodeOrCurrent(TemplateSnippetCodeVO::from($codeOtherValue))->value());
        $value->unsetCode();
        $this->assertEquals('other', $value->getCodeOrCurrent(TemplateSnippetCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('one', $value->getCodeOrCurrent(TemplateSnippetCodeVO::from($codeOtherValue))->value());
        $tenantOneValue = new TenantRef('one');
        $tenantOtherValue = new TenantRef('other');
        $copy = $value->tenant($tenantOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantRef('one'), $value->getTenant());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenant());
        $this->assertEquals(new TenantRef('one'), $value->getTenantOrCurrent(TemplateSnippetTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenantOrCurrent(TemplateSnippetTenantVO::from($tenantOtherValue))->value());
        $value->unsetTenant();
        $this->assertEquals(new TenantRef('other'), $value->getTenantOrCurrent(TemplateSnippetTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('one'), $value->getTenantOrCurrent(TemplateSnippetTenantVO::from($tenantOtherValue))->value());
        $contentHtmlOneValue = 'one';
        $contentHtmlOtherValue = 'other';
        $copy = $value->contentHtml($contentHtmlOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getContentHtml());
        $this->assertNotEquals('other', $value->getContentHtml());
        $this->assertEquals('one', $value->getContentHtmlOrCurrent(TemplateSnippetContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('other', $value->getContentHtmlOrCurrent(TemplateSnippetContentHtmlVO::from($contentHtmlOtherValue))->value());
        $value->unsetContentHtml();
        $this->assertEquals('other', $value->getContentHtmlOrCurrent(TemplateSnippetContentHtmlVO::from($contentHtmlOtherValue))->value());
        $this->assertNotEquals('one', $value->getContentHtmlOrCurrent(TemplateSnippetContentHtmlVO::from($contentHtmlOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrCurrent(TemplateSnippetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrCurrent(TemplateSnippetEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrCurrent(TemplateSnippetEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrCurrent(TemplateSnippetEnabledVO::from($enabledOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(TemplateSnippetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(TemplateSnippetVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(TemplateSnippetVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(TemplateSnippetVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
